"""Package the Cargo inputs generated by Bazel for the interpreter."""

import hashlib
import lzma
from pathlib import Path
import shutil
import subprocess
import tarfile

import compiler_bundles as bundles

ROOT = bundles.ROOT
PARSER_SOURCES = ("lib.rs", "xracklexer.rs", "xracklistener.rs", "xrackparser.rs")
NATIVE_METADATA = {"native-libraries.txt", "system-libraries.txt", "c_bindings.rs"}
TARGETS = (
    "//mlir:xrack_mlir_native",
    "//mlir:xrack_mlir_native_linkdeps",
    "//mlir:xrack_mlir_native_linkopts",
    "//mlir:xrack_mlir_cpp_runtime",
    "//mlir:c_bindings_out_dir",
    "//grammar:generate_rust",
)


def native_inputs(bazel, options, bin_dir, host, directory):
    """Produce independently compressed static libraries and generated sources."""
    missing = (bin_dir / "mlir/xrack_mlir_native_linkdeps.txt").read_text().strip()
    if missing:
        raise ValueError(f"the MLIR static library is missing Bazel link inputs: {missing}")

    windows = "windows" in host
    archive_name = "xrack_mlir_native.lib" if windows else "libxrack_mlir_native.a"
    libraries = [bin_dir / "mlir" / archive_name]
    if "darwin" not in host:
        paths = subprocess.check_output(
            (bazel, "cquery", *options, "//mlir:xrack_mlir_cpp_runtime", "--output=files"),
            cwd=ROOT,
            text=True,
            encoding="utf-8",
        ).splitlines()
        runtimes = [ROOT / path for path in paths if path.endswith((".a", ".lib"))]
        if not runtimes:
            raise ValueError(f"no Bazel C++ runtime artifacts for {host}")
        libraries.extend(sorted(runtimes, key=lambda path: path.name))
    names = [path.name for path in libraries]
    if len(names) != len(set(names)):
        raise ValueError(f"duplicate MLIR archive filenames for {host}: {names}")

    (directory / "native-libraries.txt").write_text("\n".join(names) + "\n")
    options_file = bin_dir / "mlir/xrack_mlir_native_linkopts.txt"
    system = set()
    for option in options_file.read_text().splitlines():
        if option == "-pthread":
            if "darwin" not in host:
                system.add("pthread")
        elif option.startswith("-l"):
            if "darwin" not in host or option != "-ldl":
                system.add(option[2:])
        elif option.endswith(".lib"):
            system.add(option.removesuffix(".lib"))
        elif not option.startswith("/STACK:"):
            raise ValueError(f"unrecognized Bazel MLIR link option {option!r}")
    if "darwin" in host:
        system.add("c++")
    if windows:
        system.add("msvcprt")
    (directory / "system-libraries.txt").write_text("\n".join(sorted(system)) + "\n")
    files = [(directory / name, "mlir/" + name)
             for name in ("native-libraries.txt", "system-libraries.txt")]
    for source in libraries:
        compressed = directory / (source.name + ".xz")
        with source.open("rb") as input_file, lzma.open(compressed, "wb", preset=6) as output:
            shutil.copyfileobj(input_file, output)
        # Keep COFF objects intact and distribute the compressed stream across
        # the two existing platform crates when the native archive is large.
        if windows and source.name == archive_name:
            with compressed.open("r+b") as payload:
                payload.seek(8_000_000)
                tail = payload.read()
                if tail:
                    payload.truncate(8_000_000)
                    part = directory / (compressed.name + ".tail")
                    part.write_bytes(tail)
                    files.append((part, "mlir/" + part.name))
        files.append((compressed, "mlir/" + compressed.name))
    files.append((bin_dir / "mlir/c_bindings_out_dir/c_bindings.rs", "mlir/c_bindings.rs"))
    files.extend((bin_dir / "grammar/generated/rust" / name, "antlr/" + name)
                 for name in PARSER_SOURCES)
    return files


def stage_bundle(workspace, archive, host):
    """Materialize one target crate plus the platform-independent parser sources."""
    package = workspace / "bundles/mlir" / host
    generated = workspace / "crates/xrack-parser/generated"
    generated.mkdir(exist_ok=True)
    payloads = set()
    digests = {}
    with tarfile.open(archive, "r:gz") as bundle:
        for relative, entry in bundles.archive_members(bundle, archive):
            if len(relative.parts) == 2 and relative.parts[0] == "antlr" and relative.name in PARSER_SOURCES:
                destination = generated / relative.name
                content = bundle.extractfile(entry).read().replace(b"\r\n", b"\n")
                if destination.exists() and destination.read_bytes() != content:
                    raise ValueError(f"{archive}: inconsistent generated parser source {relative}")
                destination.write_bytes(content)
                payloads.add(relative.as_posix())
            elif relative.parts[0] == "mlir" and len(relative.parts) == 2:
                if relative.name == "xrack_mlir_native.lib.xz.tail" and "windows" in host:
                    continue
                if relative.name not in NATIVE_METADATA and not relative.name.endswith(".xz"):
                    raise ValueError(f"{archive}: unexpected MLIR artifact {relative}")
                destination = package / relative.name
                with bundle.extractfile(entry) as source, destination.open("xb") as target:
                    shutil.copyfileobj(source, target)
                with destination.open("rb") as artifact:
                    digests[relative.name] = hashlib.file_digest(artifact, "sha256").hexdigest()
            elif relative.name in ("LICENSE-APACHE", "LICENSE-MIT") or relative.parts[0] == "licenses":
                destination = package.joinpath(*relative.parts)
                destination.parent.mkdir(parents=True, exist_ok=True)
                with bundle.extractfile(entry) as source, destination.open("wb") as target:
                    shutil.copyfileobj(source, target)
    if payloads != {"antlr/" + name for name in PARSER_SOURCES}:
        raise ValueError(f"{archive}: missing generated ANTLR sources")
    libraries = (package / "native-libraries.txt").read_text().splitlines()
    if (
        not libraries
        or any(Path(name).name != name or not name.endswith((".a", ".lib")) for name in libraries)
        or set(digests) != NATIVE_METADATA | {name + ".xz" for name in libraries}
    ):
        raise ValueError(f"{archive}: incomplete native MLIR package")

    manifest = package / "Cargo.toml"
    text = manifest.read_text()
    if 'publish = false' not in text or 'path = "../stub.rs"' not in text:
        raise ValueError(f"{manifest}: expected a native library placeholder")
    manifest.write_text(text.replace("publish = false\n", "").replace(
        '../stub.rs', 'src/lib.rs'
    ).replace('[package]\n', f'[package]\nlinks = "xrack_mlir_{host.replace("-", "_")}"\n'))
    shutil.copyfile(workspace / "bundles/mlir/build.rs", package / "build.rs")
    (package / "src").mkdir()
    (package / "src/lib.rs").write_text(
        '#![allow(nonstandard_style, dead_code, clippy::all)]\n'
        'include!(concat!(env!("CARGO_MANIFEST_DIR"), "/c_bindings.rs"));\n'
    )
    return digests
